Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MX = 20;
const int MXN = 400;
const int MXE = 200000;
const int INF = 199999999;

int board[MX][MX], dist[MXN], q[MXN], inq[MXN];
int adj[MXN][MXN], n, nodes, T;
string line;
int zx, zy;
int dx[4] = {0,0,-1,1}, dy[4] = {-1,1,0,0};

struct Edge {
    int u, v, cap, nxt;
} e[MXE];

int h[MXN], ecnt, s, t;
vector<tuple<int,int,int>> H, R;

int idx(int r, int c) { return (r-1)*n + c; }

bool oob(int r, int c) { return r>=1 && r<=n && c>=1 && c<=n && board[r][c] != -1; }

void init_graph() {
    nodes = n*n;
    memset(adj, -1, sizeof(adj));
    for (int r=1; r<=n; ++r)
        for (int c=1; c<=n; ++c) {
            if (board[r][c]==-1) continue;
            int u = idx(r,c);
            adj[u][u] = 0;
            for (int k=0; k<4; ++k) {
                int nr=r+dx[k], nc=c+dy[k];
                if (oob(nr,nc)) {
                    int v = idx(nr,nc);
                    adj[u][v] = 1;
                }
            }
        }
}

void spfa_src() {
    for (int i=1; i<=nodes; ++i) dist[i] = INF;
    int f=0, r=0;
    int st = idx(zx,zy);
    dist[st] = 0;
    q[r++] = st;
    while (f<r) {
        int u = q[f++];
        for (int v=1; v<=nodes; ++v)
            if (adj[u][v]==1 && dist[v]>dist[u]+1) {
                dist[v] = dist[u]+1;
                q[r++] = v;
            }
    }
}

void floyd() {
    for (int k=1; k<=nodes; ++k)
        for (int i=1; i<=nodes; ++i)
            for (int j=1; j<=nodes; ++j)
                if (adj[i][k]!=-1 && adj[k][j]!=-1)
                    if (adj[i][j]==-1 || adj[i][j]>adj[i][k]+adj[k][j])
                        adj[i][j] = adj[i][k]+adj[k][j];
}

void build_flow() {
    memset(h,-1,sizeof(h));
    ecnt=0;
    s = 0;
    t = H.size()+R.size()+1;
    for (int i=0; i<H.size(); ++i) {
        int cnt = get<2>(H[i]);
        e[ecnt] = {s, i+1, cnt, h[s]};
        h[s] = ecnt++;
        e[ecnt] = {i+1, s, 0, h[i+1]};
        h[i+1] = ecnt++;
    }
    for (int i=0; i<R.size(); ++i) {
        int cnt = get<2>(R[i]);
        e[ecnt] = {H.size()+i+1, t, cnt, h[H.size()+i+1]};
        h[H.size()+i+1] = ecnt++;
        e[ecnt] = {t, H.size()+i+1, 0, h[t]};
        h[t] = ecnt++;
    }
    int src_pos = idx(zx,zy);
    for (int i=0; i<H.size(); ++i) {
        int hr = get<0>(H[i]), hc = get<1>(H[i]);
        int hp = idx(hr,hc);
        for (int j=0; j<R.size(); ++j) {
            int rr = get<0>(R[j]), rc = get<1>(R[j]);
            int rp = idx(rr,rc);
            if (adj[hp][rp]!=-1 && adj[hp][rp]<=T) {
                if (adj[hp][rp] < dist[rp]) {
                    e[ecnt] = {i+1, H.size()+j+1, INF, h[i+1]};
                    h[i+1] = ecnt++;
                    e[ecnt] = {H.size()+j+1, i+1, 0, h[H.size()+j+1]};
                    h[H.size()+j+1] = ecnt++;
                } else if (adj[hp][rp] == dist[rp]) {
                    for (int d=0; d<4; ++d) {
                        int nr = rr+dx[d], nc = rc+dy[d];
                        if (oob(nr,nc)) {
                            int np = idx(nr,nc);
                            if (adj[hp][np] == adj[hp][rp]-1 && adj[hp][np] < dist[np]) {
                                e[ecnt] = {i+1, H.size()+j+1, INF, h[i+1]};
                                h[i+1] = ecnt++;
                                e[ecnt] = {H.size()+j+1, i+1, 0, h[H.size()+j+1]};
                                h[H.size()+j+1] = ecnt++;
                            }
                        }
                    }
                }
            }
        }
    }
}

int lvl[MXN], q2[MXN];

bool bfs_dinic() {
    memset(lvl,-1,sizeof(lvl));
    int f=0, r=0;
    q2[r++] = s;
    lvl[s] = 0;
    while (f<r) {
        int u = q2[f++];
        for (int i=h[u]; i!=-1; i=e[i].nxt) {
            int v = e[i].v;
            if (lvl[v]==-1 && e[i].cap>0) {
                lvl[v] = lvl[u]+1;
                if (v==t) return true;
                q2[r++] = v;
            }
        }
    }
    return false;
}

int dfs_dinic(int u, int flow) {
    if (u==t) return flow;
    for (int &i=h[u]; i!=-1; i=e[i].nxt) {
        int v = e[i].v;
        if (lvl[v]==lvl[u]+1 && e[i].cap>0) {
            int pushed = dfs_dinic(v, min(flow, e[i].cap));
            if (pushed>0) {
                e[i].cap -= pushed;
                e[i^1].cap += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxflow() {
    int flow=0;
    while (bfs_dinic()) {
        for (int i=0; i<=t; ++i) h[i] = -1;
        memcpy(h, h, sizeof(h));
        int f;
        while ((f=dfs_dinic(s, INF))>0) flow += f;
    }
    return flow;
}

int solve() {
    board[zx][zy] = 0;
    init_graph();
    spfa_src();
    board[zx][zy] = -1;
    init_graph();
    floyd();
    build_flow();
    return maxflow();
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> n >> T;
    H.clear(); R.clear();
    memset(board, 0, sizeof(board));
    for (int i=1; i<=n; ++i) {
        cin >> line;
        for (int j=0; j<n; ++j) {
            if (line[j]=='Y') board[i][j+1] = -1;
            else if (line[j]=='Z') {
                zx = i; zy = j+1;
                board[i][j+1] = -1;
            }
            else if (line[j]>'0' && line[j]<='9') {
                H.emplace_back(i,j+1,line[j]-'0');
            }
        }
    }
    for (int i=1; i<=n; ++i) {
        cin >> line;
        for (int j=0; j<n; ++j) {
            if (line[j]>'0' && line[j]<='9') {
                R.emplace_back(i,j+1,line[j]-'0');
            }
        }
    }
    cout << solve() << '\n';
    return 0;
}
